---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Notifications: An inbox where agent updates and mentions arrive live.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change notifications.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './notifications.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="notifications" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="ntx panel">
  <div class="ntx-h"><span class="ntx-hi" aria-hidden="true"><svg class="i s"><use href="#i-bell"/></svg></span><b>Inbox</b><span class="ntx-ct num">0</span><span class="ntx-sp"></span><button class="pill ghost sm ntx-all">Mark all read</button></div>
  <div class="ntx-tabs"><div class="seg2" role="group" aria-label="Filter"><button aria-pressed="true" data-v="all">All</button><button aria-pressed="false" data-v="agent">Agent</button><button aria-pressed="false" data-v="men">Mentions</button></div></div>
  <div class="ntx-list"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './notifications.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Notifications ---------- */
/* an inbox: a head with its name, the unread count and Mark all read, a filter, then the items, newest first. The rules
   straight under this line are the inbox's parts as the Sales CRM's notifications menu uses them (a bare .ntx in its own
   popover); the component's own card (.ntx.panel, below) sets its own measures over them */
.ntx{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.ntx-h{display:flex;align-items:center;gap:var(--dm-s-2);margin:0 -12px 2px;padding:2px var(--dm-s-3) 10px var(--dm-s-4);font-size:14px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ntx-h b{font-weight:500}
.ntx-ct{min-width:20px;height:20px;padding:0 6px;border-radius:var(--dm-r-pill);background:var(--dm-accent);color:var(--dm-on-accent);font-size:11px;font-weight:500;display:grid;place-items:center;transition:transform .35s var(--dm-ease),opacity .3s}
.ntx-ct.z{opacity:0;transform:scale(.5)}
.ntx-ct.bump{animation:ntb .45s var(--dm-ease)}
@keyframes ntb{40%{transform:scale(1.3)}}
.ntx-sp{flex:1}
.ntx-tabs .seg2 button{font-size:12px;height:26px;padding:0 9px}
.ntx-list{display:flex;flex-direction:column}
.ntx-n{display:flex;gap:10px;padding:9px var(--dm-s-2);border-radius:var(--dm-r-in);text-align:left;width:100%;position:relative;transition:background .2s}
@media (hover:hover) and (pointer:fine){.ntx-n:hover{background:var(--dm-row)}}
/* what an agent did: its icon on its status's tint (a finished run green, one that paused amber, a run that started the
   accent), in the status colours (owner, 3 Nov: saturated), never a washed-out mix; a tile given its own colour inline keeps it */
.ntx-n .ic{width:30px;height:30px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;background:var(--dm-ntx-tb,transparent);color:var(--dm-ntx-tc,var(--dm-fg2))}
.ntx-n .ic[data-tone="ok"]{--dm-ntx-tb:var(--dm-ok-bg);--dm-ntx-tc:var(--dm-ok)}
.ntx-n .ic[data-tone="warn"]{--dm-ntx-tb:var(--dm-warn-bg);--dm-ntx-tc:var(--dm-warn)}
.ntx-n .ic[data-tone="bad"]{--dm-ntx-tb:var(--dm-bad-bg);--dm-ntx-tc:var(--dm-bad)}
.ntx-n .ic[data-tone="accent"]{--dm-ntx-tb:var(--dm-accent-bg);--dm-ntx-tc:var(--dm-accent-fg)}
.ntx-n .ic[data-tone="neutral"]{--dm-ntx-tb:var(--dm-chip);--dm-ntx-tc:var(--dm-fg2)}
.ntx-n .ic .av{width:30px;height:30px;font-size:11px}
.ntx-n .t{flex:1;min-width:0;font-size:13px;line-height:1.45;color:var(--dm-fg2)}
.ntx-n .t b{font-weight:500;color:var(--dm-fg)}
.ntx-n .t span{display:block;font-size:11.5px;color:var(--dm-muted);margin-top:2px}
.ntx-n .u{width:7px;height:7px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent));margin-top:6px;flex:none;transition:transform .3s var(--dm-ease),opacity .3s}
.ntx-n.read .u{transform:scale(0);opacity:0}
.ntx-n.read .t{color:var(--dm-muted)}
.ntx-n.new{animation:ntn .6s var(--dm-ease) both}
@keyframes ntn{from{opacity:0;transform:translateY(-10px);filter:blur(4px)}}
.ntx-e{padding:40px 10px;text-align:center;font-size:13px;color:var(--dm-muted)}
/* the component's own card. It sits on two columns (owner, 18 Nov), its content 16px from every edge in every style: the
   head's neutral mark (the inbox's bell) in a 30px column with each item's icon or avatar centred under it, and the inbox's
   name and each item's words 12px after it; Mark all read's words and the unread dots end on the content's right edge. The
   head's hairline runs from edge to edge with 16px under it. An item is a button, so its hover fill reaches 8px out round it,
   a quiet fill that shows in light mode too, with the card's corners less 8. A read item keeps its colours (owner, 20 Nov:
   nothing fades to say it is past): only its unread dot goes. The card keeps no room for items to come: it grows as they
   arrive (grow()), centred in its stage */
.ntx.panel{padding:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.ntx.panel .ntx-h{gap:var(--dm-s-3);margin:0 calc(-1 * var(--dm-s-4)) var(--dm-s-2);padding:0 var(--dm-s-4) var(--dm-s-4);line-height:20px}
.ntx-hi{width:30px;height:30px;display:grid;place-items:center;flex:none;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2)}
.ntx.panel .ntx-ct{margin-left:calc(-1 * var(--dm-s-1))}
/* Mark all read is a text button: its words end on the content's edge and its hover box reaches out round them */
.ntx.panel .ntx-all.pill{padding:0 var(--dm-s-2);margin-right:calc(-1 * var(--dm-s-2))}
.ntx.panel .ntx-tabs{display:flex}
.ntx.panel .ntx-list{margin:0 calc(-1 * var(--dm-s-2)) calc(-1 * var(--dm-s-2))}
.ntx.panel .ntx-n{align-items:center;gap:var(--dm-s-3);padding:var(--dm-s-2);border-radius:calc(var(--dm-r-card) - var(--dm-s-2));transition:background-color var(--dm-t-fast)}
.ntx.panel .ntx-n .t span{line-height:15px}
.ntx.panel .ntx-n .u{margin-top:0}
.ntx.panel .ntx-n.read .t{color:var(--dm-fg2)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.ntx.panel :is(.pill,.ntx-n):active{transform:none}
/* an empty filter: a small sketch of a list on a white card, a title and one muted line (Clean's empty state, in every style) */
.ntx-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:var(--dm-s-6) var(--dm-s-4) var(--dm-s-4);text-align:center}
.ntx-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.ntx-em>span:not(.ntx-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.ntx-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 var(--dm-s-4);border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.ntx-em-art::before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border-radius:50%;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-row))}
.ntx-em-art::after{content:"";position:absolute;left:32px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-row))}
:root:not([data-style="soft"],[data-style="clean"]) .ntx-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:inset 0 0 0 1px var(--dm-line)}
/* Clean: the head's mark has a hairline like the other tiles, and a new item rises in without a blur */
:root[data-style="clean"] .ntx-hi,:root [data-style="clean"] .ntx-hi,:root [data-style="clean"].ntx-hi{box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .ntx.panel .ntx-n.new,:root [data-style="clean"] .ntx.panel .ntx-n.new,:root [data-style="clean"].ntx.panel .ntx-n.new{animation:clpiece var(--dm-t-slow) var(--dm-ease) both}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, AV, DM, I, grow, hoverGlide, html, seg, stagger } from '../core/core.js';
DM.def('notifications', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{bell}', I('bell'));
  // Clean's one hover: a highlight that glides from row to row (hoverGlide)
  c.offs.push(hoverGlide($('.ntx', r), '.ntx-n'));
  // what the agent did shows its icon on its status's tint (tone: ok, warn, bad, accent or neutral); people show their avatar
  let N = [
    { k:'agent', ic:'ok', tone:'ok', t:'<b>Pricing audit</b> finished. 2 fixes ready to review', w:'4 min ago' },
    { k:'men', av:['MK','var(--dm-av-l)'], t:'<b>Maya</b> mentioned you in Checkout flow', w:'20 min ago' },
    { k:'agent', ic:'alert', tone:'warn', t:'<b>Token export</b> paused at the $5 cap', w:'1 hour ago' },
    { k:'men', av:['JO','var(--dm-av-m)'], t:'<b>Jon</b> asked for your review on PR #284', w:'2 hours ago', read:true }
  ];
  const root = r.classList.contains('ntx') ? r : $('.ntx', r), list = $('.ntx-list', r), ct = $('.ntx-ct', r); let f = 'all';
  const count = (bump) => { const n = N.filter(x => !x.read).length; ct.textContent = n; ct.classList.toggle('z', !n); if (bump){ ct.classList.remove('bump'); void ct.offsetWidth; ct.classList.add('bump'); } };
  const row = x => `<button class="ntx-n${x.read ? ' read' : ''}" aria-pressed="${!!x.read}"><span class="ic"${x.ic ? ` data-tone="${x.tone || 'neutral'}"` : ''}>${x.ic ? I(x.ic,'xs') : AV(x.av[0], x.av[1])}</span><span class="t">${x.t}<span>${x.w}</span></span><span class="u"></span></button>`;
  const flip = (b, x) => { x.read = !x.read; b.classList.toggle('read', x.read); b.setAttribute('aria-pressed', x.read); count(); };
  // an empty filter shows Clean's empty state: a small sketch of a list, a title and one muted line
  const EMPTY = '<div class="ntx-em"><span class="ntx-em-art" aria-hidden="true"></span><b>Nothing here yet</b><span>New updates and mentions show up here</span></div>';
  function paint(anim){ const L = N.filter(x => f === 'all' || x.k === f); list.innerHTML = L.length ? L.map(row).join('') : EMPTY;
    $$('.ntx-n', list).forEach((b, i) => b.onclick = () => flip(b, L[i]));
    if (anim) stagger($$('.ntx-n', list), 40); count(); }
  seg($('.ntx-tabs .seg2', r), v => { f = v; paint(true); });
  $('.ntx-all', r).onclick = () => { N.forEach(x => x.read = true); $$('.ntx-n', list).forEach((b, i) => c.later(i * 50, () => { b.classList.add('read'); b.setAttribute('aria-pressed', 'true'); })); count(); };
  paint(true);
  // the card fits its items at every moment (owner, 17 and 18 Nov: no room kept for the ones to come): it eases taller as one
  // arrives or a filter shows more, and shorter as one shows fewer, centred in its stage (grow(), once its entrance has ended)
  if (root) Promise.resolve().then(() => Promise.all(root.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && root.isConnected) c.offs.push(grow(root)); });
  const incoming = [{ k:'agent', ic:'spark', tone:'accent', t:'<b>Weekly design QA</b> started on 12 frames', w:'Just now' }, { k:'men', av:['AR','var(--dm-av-p)'], t:'<b>Ari</b> replied: “Looks great, ship it”', w:'Just now' }];
  // two items arrive while you watch; once you click or type in the inbox the preview leaves it to you, so a tab you
  // picked or a Mark all read stays as you left it
  incoming.forEach((x, i) => c.later(2200 + i * 2600, () => { if (c.mine) return; N.unshift(x); if (f === 'all' || f === x.k){ const el = html(row(x)); el.classList.add('new'); list.prepend(el); $('.ntx-em', list)?.remove(); el.onclick = () => flip(el, x); } count(true); }));
});
